function b64ToBytes(ctx, s){
  var T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  s = String(s).replace(/[-_]/g, function(c){ return c === '-' ? '+' : '/'; }).replace(/[^A-Za-z0-9+\/=]/g, '');
  var out = [];
  var buffer = 0, bits = 0;
  for (var i = 0; i < s.length; i++) {
    var v = T.indexOf(s[i]);
    if (v < 0) continue;
    buffer = (buffer << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out.push((buffer >> bits) & 255);
    }
  }
  return out;
}
function bytesToB64(ctx, bytes){
  var T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  var out = '';
  for (var i = 0; i < bytes.length; i += 3) {
    var b0 = bytes[i];
    var b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    var b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    out += T[b0 >> 2];
    out += T[((b0 & 3) << 4) | (b1 >> 4)];
    out += (i + 1 < bytes.length) ? T[((b1 & 15) << 2) | (b2 >> 6)] : '=';
    out += (i + 2 < bytes.length) ? T[b2 & 63] : '=';
  }
  return out;
}
function utf8FromBytes(ctx, bytes){
